using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CosmicExpansionEffect", menuName = "Data/Battle/Effects/Orion/CosmicExpansion Effect")]
public class CosmicExpansionEffect : Effect
{
	[Header("CosmicExpansion Effect")]
	[SerializeField]
	private BattleAction purifyAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedDescription = GetLocalizedDescription();
		string text = purifyAction.GetActionDescription(LanguagesIndexes.IsCurrentLanguageLatinLanguage() ? (-4) : (-3)).LowercaseFirst();
		if (LanguagesIndexes.IsCurrentLanguageKorean())
		{
			text = text.Replace("의 ", "");
		}
		localizedDescription = ((amount != EffectsValues.NO_VALUE) ? Smart.Format(localizedDescription, amount, text) : GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, GetNumberToReplaceWithX(), text));
		return localizedDescription + AppendedDescription();
	}
}
